#include "StdAfx.h"#include "FscList.h"static char* sid = "Signal Convertion";//struct SSignalConvertion{  UINT in;  UINT out;  double value;};bool SFscList::FuncParser48( VAR_PARSER ){  FuncParserdo(fsc,p,dat,tmp);    SSignalConvertion io;  memset( &io, -1, sizeof(io) );  SDotValue out(enumValueInt);  switch( dat.data[1] )  {  case 'L':    out.eType = enumValueInt;    break;  default:    ASSD(0);  }  switch( dat.data[0] )  {  case 'F':    break;  default:    ASSD(0);  }  io.out = fsc->AddFscDots(&out);  p.nBuff = fsc->AddFscBuff( &io, sizeof(io) );  ns_UT::SLocalTmp* item = tmp.Item();  item->nCount = 1;  item->dim[0] = io.out;  return true;}////void FuncDebugs48( VAR_DEBUGS )//  {//  strcat_s( str, sid );//  strcat_s( str, "\r\n------------------------------------------------------------\r\n" );//  FuncDebugsdo( p, str );//  }//void SFscList::FuncPaints48( VAR_PAINTS ){  COLORREF color = 0x808080;  SDotValue* O = NULL;  SDotValue* I = NULL;  if ( p.nBuff != -1 )  {    SSignalConvertion* dat = (SSignalConvertion*)fsc->Data(p.nBuff);    O = fsc->DotV(dat->out);    I = fsc->DotV(dat->in);    if( !I || !O )      color = BADCOLOR;    else if ( p.nBuff == nSelect )      color = SELCOLOR;  }  RECT rcr = p.rect;   CMyPen pen( font, color );  pen.Rect( rcr );  POINT pt0[2] = {{rcr.left,rcr.bottom},{rcr.right,rcr.top}};  pen.Points( pt0, _countof(pt0), 0 );  //  if( I )    p.DrawL( font, rcr, enumValueDbl==I->eType ? "F" : "L", 0 );  if( O )    p.DrawR( font, rcr, enumValueDbl==O->eType ? "F" : "L", 2 );}//void SFscList::FuncSetLnk48( VAR_SETLNK ){  if ( nLink == -1 )     return;  if ( x == p.rect.right )     return;  //  SSignalConvertion* dat = (SSignalConvertion*)fsc->Data(p.nBuff);  dat->in = nLink;}////-----------------------------------------------------------------------------//UINT FuncCursor48( VAR_CURSOR )//  {//  return p.nBuff;//  }////-----------------------------------------------------------------------------UINT* SFscList::FuncOutput48( VAR_OUTPUT ){  n = 1;  SSignalConvertion* dat = (SSignalConvertion*)fsc->Data(p.nBuff);  return &dat->out;}////-----------------------------------------------------------------------------void SFscList::FuncTimers48( VAR_TIMERS ){  if( dt == 0 )    return;  SSignalConvertion* dat = (SSignalConvertion*)fsc->Data(p.nBuff);  SDotValue* O = fsc->DotV(dat->out);  SDotValue* I = fsc->DotV(dat->in);  if( !I || !O )    return;  double value = I->Dbl();  if( enumValueInt==I->eType )    value = I->nVal;  switch( O->eType )  {  case enumValueInt:    O->nVal = (int)value;    break;  default:    O->Set( value );  }}////-----------------------------------------------------------------------------static LPCSTR s_pName[] = { "out" };int SFscList::FuncQuickWatch48( IFscStorage* fsc, LFscBase *obj, IFscStorage::SVarInfo *pvi, int cVI, LPCSTR *ppPntName ){  return 0;}int SFscList::SaveState48( IStateSer *psaver, IFscStorage* fsc, LFscBase *obj ){  SSignalConvertion* dat = (SSignalConvertion*)fsc->Data(obj->nBuff);  SDotValue* vals[] = { fsc->DotV(dat->out) };  for( int i=0; i<_countof(vals); ++i )  {    psaver->WriteDotV( vals[i], s_pName[i] );  }  return 0;}int SFscList::RestoreState48( IStateSer *prest, IFscStorage* fsc, LFscBase *obj ){  SSignalConvertion* dat = (SSignalConvertion*)fsc->Data(obj->nBuff);  SDotValue* vals[] = { fsc->DotV(dat->out) };  for( int i=0; i<_countof(vals); ++i )  {    prest->ReadDotV( vals[i], s_pName[i] );  }  return 0;}